const repos = [
  "InoriMutsumi/dsh-grill-first",
  "jiezeng2004-design/dsh-requirements-alignment",
  "Inference1/clarify-intent-and-establish-shared-understanding",
  "Aik358/dsh-memory-fitting",
];
const cmd = repos.map(r => `
Write-Output "===== ${r} ====="
foreach ($b in @('main','master')) {
  try {
    $u = "https://raw.githubusercontent.com/${r}/$b/README.md"
    $x = Invoke-WebRequest -Uri $u -UseBasicParsing -TimeoutSec 20
    $x.Content.Substring(0,[Math]::Min(5000,$x.Content.Length)); break
  } catch { Write-Output ("ERR " + $b + ": " + $_.Exception.Message) }
}
`).join("\n");
const r = await tools.pwsh({ description: "Fetch candidate plugin READMEs", command: cmd, timeoutMs: 120000 });
if (r.kind === "foreground") console.log(r.stdout.text.slice(0, 20000));
